/* Course geometry, themes, and the built-in set of timed maps. */

export const CELL = 2.4;
export const STEP = 1.2;
export const GRID_MIN = -11;
export const GRID_MAX = 11;
export const LEVELS = 6;
export const MARBLE_RADIUS = 0.5;

export const PIECE_TYPES = [
  'plat', 'ramp', 'wall', 'spinner', 'mover', 'boost', 'bounce', 'beam', 'checkpoint', 'start', 'finish',
];

export const THEMES = {
  sunrise: {
    id: 'sunrise',
    name: 'Sunrise',
    skyTop: '#4f8fd8',
    skyMid: '#ffd3a3',
    skyBottom: '#ffe9c7',
    sun: '#fff4c9',
    fog: '#f7c99b',
    hemiSky: '#cfe7ff',
    hemiGround: '#c27e50',
    light: '#fff0d2',
    body: '#fff3df',
    bodySide: '#ffb964',
    top: '#fffaf0',
    rock: '#d4794a',
    accent: '#ff5f3d',
    accent2: '#ffbf2f',
    glow: '#ffd166',
    cloud: '#fff7e9',
    grass: '#7fd07a',
  },
  neon: {
    id: 'neon',
    name: 'Neon',
    skyTop: '#070822',
    skyMid: '#29134f',
    skyBottom: '#5d1d69',
    sun: '#ff4fd8',
    fog: '#1a0c34',
    hemiSky: '#7f6bff',
    hemiGround: '#1b0a2b',
    light: '#b7b0ff',
    body: '#23234d',
    bodySide: '#141433',
    top: '#3a3a74',
    rock: '#140d2b',
    accent: '#2de2e6',
    accent2: '#ff2e88',
    glow: '#67fff6',
    cloud: '#342361',
    grass: '#2de2e6',
  },
  temple: {
    id: 'temple',
    name: 'Temple',
    skyTop: '#0c3550',
    skyMid: '#63c9be',
    skyBottom: '#d6f4d5',
    sun: '#fff3ba',
    fog: '#9bd8cb',
    hemiSky: '#d8fff4',
    hemiGround: '#2a5c48',
    light: '#fff4d0',
    body: '#f0e6c8',
    bodySide: '#8a7a52',
    top: '#fff8dd',
    rock: '#4e6b4c',
    accent: '#ffb627',
    accent2: '#ff6b6b',
    glow: '#ffe28a',
    cloud: '#e8fff9',
    grass: '#67b86b',
  },
};

function themeOf(map) {
  return THEMES[map.theme] || THEMES.sunrise;
}

function piece(t, x, z, l = 0, r = 0, extra = {}) {
  return { t, x, z, l, r, ...extra };
}

function addRow(list, x, z, dx, dz, n, l = 0, r = 0, type = 'plat') {
  for (let i = 0; i < n; i++) list.push(piece(type, x + dx * i, z + dz * i, l, r));
}

function addLine(list, cells, l, type = 'plat', r = 0) {
  for (const [x, z] of cells) list.push(piece(type, x, z, l, r));
}

/* ------------------------------------------------------------------ */
/* 1 — Sunrise Sprint                                                   */
/* ------------------------------------------------------------------ */
const sunrisePieces = [];
sunrisePieces.push(piece('start', 5, 10, 0, 2));
addRow(sunrisePieces, 5, 9, 0, -1, 3, 0);              // 9,8,7
addRow(sunrisePieces, 5, 5, 0, -1, 2, 0);              // 5,4
sunrisePieces.push(piece('ramp', 5, 3, 0, 2));         // up to level 1
addRow(sunrisePieces, 5, 2, 0, -1, 3, 1);              // 2,1,0
sunrisePieces.push(piece('checkpoint', 5, 1, 1, 2));
addRow(sunrisePieces, 4, 0, -1, 0, 2, 1);              // 4,3
sunrisePieces.push(piece('spinner', 3, 0, 1, 0));      // replaces tile at 3
sunrisePieces.push(piece('plat', 2, 0, 1, 0));
sunrisePieces.push(piece('plat', 0, 0, 1, 0));         // one-cell gap at 1
sunrisePieces.push(piece('boost', -1, 0, 1, 3));
sunrisePieces.push(piece('plat', -2, 0, 1, 0));
sunrisePieces.push(piece('plat', -3, 0, 1, 0));
sunrisePieces.push(piece('mover', -4, 0, 1, 3));       // glides along x
sunrisePieces.push(piece('plat', -6, 0, 1, 0));
sunrisePieces.push(piece('checkpoint', -6, 1, 1, 0));
sunrisePieces.push(piece('plat', -6, 2, 1, 0));
sunrisePieces.push(piece('ramp', -6, 3, 0, 0));        // down to ground
addRow(sunrisePieces, -6, 4, 0, 1, 2, 0);              // 4,5
addRow(sunrisePieces, -6, 7, 0, 1, 2, 0);              // 7,8
sunrisePieces.push(piece('finish', -6, 9, 0, 0));

/* ------------------------------------------------------------------ */
/* 2 — Neon Current                                                     */
/* ------------------------------------------------------------------ */
const neonPieces = [];
neonPieces.push(piece('start', 0, 13, 0, 2));
addRow(neonPieces, 0, 12, 0, -1, 2, 0);                // 12,11
neonPieces.push(piece('ramp', 0, 10, 0, 2));
neonPieces.push(piece('checkpoint', 0, 9, 1, 2));
neonPieces.push(piece('spinner', 0, 8, 1, 0));
neonPieces.push(piece('plat', 0, 7, 1, 0));
addRow(neonPieces, 1, 7, 1, 0, 2, 1);                  // 1,2
neonPieces.push(piece('checkpoint', 2, 7, 1, 0));
neonPieces.push(piece('plat', 4, 7, 1, 0));            // gap at 3
neonPieces.push(piece('ramp', 5, 7, 1, 1));            // up toward +x
neonPieces.push(piece('plat', 6, 7, 2, 0));
neonPieces.push(piece('plat', 6, 6, 2, 0));
neonPieces.push(piece('mover', 6, 5, 2, 2));           // rides along z
neonPieces.push(piece('plat', 6, 3, 2, 0));
neonPieces.push(piece('checkpoint', 6, 3, 2, 0));
neonPieces.push(piece('ramp', 6, 2, 1, 0));            // down toward +z
neonPieces.push(piece('plat', 6, 1, 1, 0));
neonPieces.push(piece('boost', 6, 0, 1, 2));
neonPieces.push(piece('plat', 6, -2, 1, 0));           // gap at -1
neonPieces.push(piece('plat', 6, -3, 1, 0));
neonPieces.push(piece('spinner', 6, -4, 1, 0));
addRow(neonPieces, 5, -4, -1, 0, 2, 1);                // 5,4
neonPieces.push(piece('checkpoint', 3, -4, 1, 3));
neonPieces.push(piece('ramp', 2, -4, 1, 3));
neonPieces.push(piece('plat', 1, -4, 2, 0));
neonPieces.push(piece('beam', 0, -5, 2, 3));
neonPieces.push(piece('beam', -1, -5, 2, 3));
neonPieces.push(piece('beam', -2, -5, 2, 3));
neonPieces.push(piece('plat', -3, -5, 1, 0));
neonPieces.push(piece('ramp', -3, -6, 1, 2));
neonPieces.push(piece('plat', -3, -7, 2, 0));
neonPieces.push(piece('finish', -3, -8, 2, 2));

/* ------------------------------------------------------------------ */
/* 3 — Sky Temple                                                       */
/* ------------------------------------------------------------------ */
const templePieces = [];
templePieces.push(piece('start', 0, 15, 2, 2));
templePieces.push(piece('plat', 0, 14, 2, 0));
templePieces.push(piece('plat', 0, 12, 2, 0));         // gap at 13
templePieces.push(piece('spinner', 0, 11, 2, 0));
templePieces.push(piece('checkpoint', 0, 10, 2, 0));
templePieces.push(piece('plat', 1, 10, 2, 0));
templePieces.push(piece('plat', 2, 10, 2, 0));
templePieces.push(piece('bounce', 3, 10, 2, 0));       // launches over the gap
templePieces.push(piece('plat', 3, 8, 2, 0));
templePieces.push(piece('plat', 3, 7, 2, 0));
templePieces.push(piece('ramp', 3, 6, 2, 2));
templePieces.push(piece('plat', 3, 5, 3, 0));
templePieces.push(piece('checkpoint', 3, 4, 3, 0));
templePieces.push(piece('beam', 2, 4, 3, 3));
templePieces.push(piece('beam', 1, 4, 3, 3));
templePieces.push(piece('beam', 0, 4, 3, 3));
templePieces.push(piece('spinner', 0, 3, 3, 0));
templePieces.push(piece('mover', 0, 2, 3, 2));
templePieces.push(piece('plat', 0, 0, 3, 0));
templePieces.push(piece('boost', 0, -1, 3, 2));
templePieces.push(piece('plat', 0, -3, 3, 0));         // boost gap
templePieces.push(piece('finish', 0, -4, 3, 2));

export const BUILTIN_MAPS = [
  {
    id: 'sunrise-sprint',
    name: 'Sunrise Sprint',
    tagline: 'Warm up those bearings.',
    author: 'Marble Club',
    theme: 'sunrise',
    difficulty: 1,
    par: 27,
    rivals: [
      { name: 'Nova', time: 20.4, color: '#ff6b35' },
      { name: 'Pixel', time: 22.6, color: '#2d9cdb' },
      { name: 'Mika', time: 24.9, color: '#9b51e0' },
      { name: 'Rook', time: 28.1, color: '#27ae60' },
      { name: 'Juno', time: 31.8, color: '#eb5757' },
    ],
    pieces: sunrisePieces,
  },
  {
    id: 'neon-current',
    name: 'Neon Current',
    tagline: 'A glowing route through the grid.',
    author: 'Marble Club',
    theme: 'neon',
    difficulty: 2,
    par: 43,
    rivals: [
      { name: 'Vex', time: 33.9, color: '#2de2e6' },
      { name: 'Lumi', time: 37.2, color: '#ff2e88' },
      { name: 'Kodi', time: 40.8, color: '#f2c94c' },
      { name: 'Zephyr', time: 45.1, color: '#b06bff' },
      { name: 'Ash', time: 50.4, color: '#6fcf97' },
    ],
    pieces: neonPieces,
  },
  {
    id: 'sky-temple',
    name: 'Sky Temple',
    tagline: 'Narrow beams. Big air. No fear.',
    author: 'Marble Club',
    theme: 'temple',
    difficulty: 3,
    par: 60,
    rivals: [
      { name: 'Kite', time: 45.7, color: '#ffb627' },
      { name: 'Sable', time: 50.2, color: '#56ccf2' },
      { name: 'Onyx', time: 55.5, color: '#bb6bd9' },
      { name: 'Pip', time: 61.3, color: '#ff6b6b' },
      { name: 'Moss', time: 67.8, color: '#6fcf97' },
    ],
    pieces: templePieces,
  },
];

export function getBuiltin(id) {
  return BUILTIN_MAPS.find((m) => m.id === id) || null;
}

export function starterMap() {
  const pieces = [];
  pieces.push(piece('start', 0, 5, 0, 2));
  pieces.push(piece('plat', 0, 4, 0, 0));
  pieces.push(piece('plat', 0, 3, 0, 0));
  pieces.push(piece('ramp', 0, 2, 0, 2));
  pieces.push(piece('checkpoint', 0, 1, 1, 0));
  pieces.push(piece('plat', 1, 1, 1, 0));
  pieces.push(piece('plat', 2, 1, 1, 0));
  pieces.push(piece('spinner', 3, 1, 1, 0));
  pieces.push(piece('plat', 4, 1, 1, 0));
  pieces.push(piece('plat', 4, 0, 1, 0));
  pieces.push(piece('plat', 4, -1, 1, 0));
  pieces.push(piece('finish', 4, -2, 1, 2));
  return {
    id: 'draft',
    name: 'Untitled Course',
    tagline: 'A course made by you.',
    author: 'You',
    theme: 'sunrise',
    difficulty: 2,
    par: 35,
    rivals: [],
    pieces,
  };
}

export function courseBounds(pieces) {
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity, minL = 0, maxL = 0;
  for (const p of pieces) {
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
    minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
    minL = Math.min(minL, p.l); maxL = Math.max(maxL, p.l);
  }
  if (!pieces.length) return { minX: -2, maxX: 2, minZ: -2, maxZ: 2, minL: 0, maxL: 0 };
  return { minX, maxX, minZ, maxZ, minL, maxL };
}

export function estimatedPar(pieces) {
  const b = courseBounds(pieces);
  const span = (b.maxX - b.minX + b.maxZ - b.minZ + 2) * 2.3;
  return Math.max(12, Math.round(span + pieces.length * 0.22));
}

export { themeOf };

/* Local persistence, leaderboards, and shareable challenge codes. */

const KEY = 'marble-rush-v1';
const MAX_CUSTOM = 40;

const defaults = () => ({
  v: 1,
  settings: { sound: true, tilt: false, quality: 'auto', ghost: true },
  records: {},
  custom: [],
  draft: null,
});

function safeParse(raw) {
  try {
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') return defaults();
    const d = defaults();
    return {
      ...d,
      ...parsed,
      settings: { ...d.settings, ...(parsed.settings || {}) },
      records: parsed.records && typeof parsed.records === 'object' ? parsed.records : {},
      custom: Array.isArray(parsed.custom) ? parsed.custom : [],
    };
  } catch {
    return defaults();
  }
}

export const store = {
  data: safeParse((() => { try { return localStorage.getItem(KEY); } catch { return null; } })()),

  persist() {
    try {
      localStorage.setItem(KEY, JSON.stringify(this.data));
      return true;
    } catch {
      // Storage is full: shed the fattest ghost replays first, then retry.
      for (const id of Object.keys(this.data.records)) {
        if (this.data.records[id]?.ghost) {
          delete this.data.records[id].ghost;
          try { localStorage.setItem(KEY, JSON.stringify(this.data)); return true; } catch { /* keep shedding */ }
        }
      }
      return false;
    }
  },

  record(mapId) {
    return this.data.records[mapId] || null;
  },

  bestMs(mapId) {
    return this.data.records[mapId]?.best ?? null;
  },

  saveBest(mapId, ms, ghost, splits = null) {
    const prev = this.data.records[mapId] || {};
    if (!prev.best || ms < prev.best) {
      this.data.records[mapId] = { ...prev, best: Math.round(ms), ghost: ghost || null, splits, date: Date.now() };
      this.persist();
      return true;
    }
    this.data.records[mapId] = { ...prev, attempts: (prev.attempts || 0) + 1 };
    this.persist();
    return false;
  },

  bumpAttempt(mapId) {
    const prev = this.data.records[mapId] || {};
    this.data.records[mapId] = { ...prev, attempts: (prev.attempts || 0) + 1 };
    this.persist();
  },

  setSetting(key, value) {
    this.data.settings[key] = value;
    this.persist();
  },

  customMaps() {
    return this.data.custom;
  },

  getCustom(id) {
    return this.data.custom.find((m) => m.id === id) || null;
  },

  addCustom(map) {
    const clean = this.data.custom.filter((m) => m.id !== map.id);
    clean.unshift(map);
    this.data.custom = clean.slice(0, MAX_CUSTOM);
    this.persist();
  },

  removeCustom(id) {
    this.data.custom = this.data.custom.filter((m) => m.id !== id);
    delete this.data.records[id];
    this.persist();
  },

  saveDraft(map) {
    this.data.draft = map;
    this.persist();
  },

  clearDraft() {
    this.data.draft = null;
    this.persist();
  },

  allMaps() {
    return [...this.data.custom, ...builtinFallback()];
  },
};

// Filled in by main.js to avoid a circular import with maps.js.
let builtinFallback = () => [];
export function setBuiltinProvider(fn) {
  builtinFallback = fn;
}

export function leaderboardFor(map, includeYou = true) {
  const rows = [];
  for (const r of map.rivals || []) {
    rows.push({ name: r.name, time: r.time, color: r.color || '#ffb86b', you: false });
  }
  if (map.creatorBest) {
    rows.push({ name: map.creatorName || 'Creator', time: map.creatorBest / 1000, color: '#7dd3fc', you: false, creator: true });
  }
  const best = store.bestMs(map.id);
  if (includeYou && best) {
    rows.push({ name: 'You', time: best / 1000, color: '#ff6b35', you: true });
  }
  rows.sort((a, b) => a.time - b.time);
  return rows;
}

export function rankFor(map) {
  const best = store.bestMs(map.id);
  if (!best) return null;
  const rows = leaderboardFor(map, true);
  const index = rows.findIndex((r) => r.you);
  return index >= 0 ? index + 1 : null;
}

export function formatTime(ms, showMs = true) {
  if (ms == null || Number.isNaN(ms)) return '--:--.---';
  const total = Math.max(0, ms);
  const minutes = Math.floor(total / 60000);
  const seconds = Math.floor((total % 60000) / 1000);
  const millis = Math.floor(total % 1000);
  const base = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
  return showMs ? `${base}.${String(millis).padStart(3, '0')}` : base;
}

export function formatShort(seconds) {
  if (seconds == null) return '--';
  return seconds < 60 ? seconds.toFixed(2) : formatTime(seconds * 1000, false);
}

export function formatDelta(ms) {
  if (ms == null || Number.isNaN(ms)) return '';
  const sign = ms <= 0 ? '−' : '+';
  const abs = Math.abs(ms);
  return `${sign}${(abs / 1000).toFixed(2)}s`;
}

export function medalFor(ms, parSeconds) {
  if (!ms || !parSeconds) return 'bronze';
  const seconds = ms / 1000;
  if (seconds <= parSeconds * 0.82) return 'gold';
  if (seconds <= parSeconds) return 'silver';
  if (seconds <= parSeconds * 1.45) return 'bronze';
  return 'finisher';
}

/* ---------------- challenge codes ---------------- */

function bytesToB64(bytes) {
  let out = '';
  for (let i = 0; i < bytes.length; i += 0x8000) {
    out += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
  }
  return btoa(out).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
}

function b64ToBytes(str) {
  const b64 = str.replace(/-/g, '+').replace(/_/g, '/');
  const padded = b64 + '='.repeat((4 - (b64.length % 4)) % 4);
  const raw = atob(padded);
  const bytes = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
  return bytes;
}

export function encodeChallenge(map, bestMs = null) {
  const payload = {
    v: 1,
    n: map.name,
    a: map.author || 'Anon',
    g: map.tagline || '',
    t: map.theme || 'sunrise',
    p: map.par || 30,
    d: map.difficulty || 2,
    b: bestMs || null,
    pieces: map.pieces.map((p) => ({ t: p.t, x: p.x, z: p.z, l: p.l, r: p.r || 0 })),
  };
  const bytes = new TextEncoder().encode(JSON.stringify(payload));
  return `MR1.${bytesToB64(bytes)}`;
}

const VALID = new Set(['plat', 'ramp', 'wall', 'spinner', 'mover', 'boost', 'bounce', 'beam', 'checkpoint', 'start', 'finish']);

export function decodeChallenge(code) {
  const text = String(code || '').trim();
  const body = text.startsWith('MR1.') ? text.slice(4) : text;
  if (!body || body.length > 200000) throw new Error('That code looks incomplete.');
  let payload;
  try {
    payload = JSON.parse(new TextDecoder().decode(b64ToBytes(body)));
  } catch {
    throw new Error('That challenge code is not valid.');
  }
  if (!payload || payload.v !== 1 || !Array.isArray(payload.pieces)) throw new Error('Unrecognized challenge code.');
  if (payload.pieces.length < 2 || payload.pieces.length > 1200) throw new Error('That course has an unusual size.');
  const pieces = [];
  for (const p of payload.pieces) {
    if (!p || !VALID.has(p.t)) continue;
    const x = Math.round(Number(p.x));
    const z = Math.round(Number(p.z));
    const l = Math.max(0, Math.min(5, Math.round(Number(p.l) || 0)));
    if (!Number.isFinite(x) || !Number.isFinite(z) || Math.abs(x) > 40 || Math.abs(z) > 40) continue;
    pieces.push({ t: p.t, x, z, l, r: Math.abs(Math.round(Number(p.r) || 0)) % 4 });
  }
  if (!pieces.some((p) => p.t === 'start') || !pieces.some((p) => p.t === 'finish')) {
    throw new Error('That course is missing a start or finish.');
  }
  return {
    id: `u-${Date.now().toString(36)}-${Math.floor(Math.random() * 999)}`,
    name: cleanName(payload.n || 'Shared Course', 34),
    author: cleanName(payload.a || 'Anon', 22),
    tagline: cleanName(payload.g || 'A shared marble course.', 80),
    theme: ['sunrise', 'neon', 'temple'].includes(payload.t) ? payload.t : 'sunrise',
    par: Math.max(8, Math.min(300, Number(payload.p) || 30)),
    difficulty: Math.max(1, Math.min(3, Number(payload.d) || 2)),
    pieces,
    creatorBest: Number.isFinite(payload.b) && payload.b > 2000 && payload.b < 3600000 ? Number(payload.b) : null,
    creatorName: cleanName(payload.a || 'Creator', 22),
    createdAt: Date.now(),
    shared: true,
  };
}

export function cleanName(value, max = 30) {
  return String(value || '')
    .replace(/[<>&"]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max);
}

export function newMapId() {
  return `u-${Date.now().toString(36)}-${Math.floor(Math.random() * 9999)}`;
}

/* Tiny procedural sound engine — no audio files, works offline. */

export class GameAudio {
  constructor() {
    this.enabled = true;
    this.ctx = null;
    this.master = null;
    this.rollGain = null;
    this.rollFilter = null;
    this.lastCollide = 0;
    this.noiseBuffer = null;
  }

  init() {
    if (this.ctx) return;
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.enabled ? 0.55 : 0;
    this.master.connect(this.ctx.destination);

    const length = Math.floor(this.ctx.sampleRate * 2);
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      data[i] = last * 3.2;
    }
    this.noiseBuffer = buffer;

    const src = this.ctx.createBufferSource();
    src.buffer = buffer;
    src.loop = true;
    this.rollFilter = this.ctx.createBiquadFilter();
    this.rollFilter.type = 'lowpass';
    this.rollFilter.frequency.value = 420;
    this.rollFilter.Q.value = 0.7;
    this.rollGain = this.ctx.createGain();
    this.rollGain.gain.value = 0;
    src.connect(this.rollFilter).connect(this.rollGain).connect(this.master);
    src.start();
  }

  unlock() {
    this.init();
    if (this.ctx?.state === 'suspended') this.ctx.resume();
  }

  setEnabled(on) {
    this.enabled = on;
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(on ? 0.55 : 0, this.ctx.currentTime, 0.04);
    }
  }

  setRolling(speed, grounded) {
    if (!this.ctx || !this.rollGain) return;
    const target = grounded ? Math.min(1, speed / 13) * 0.07 : 0;
    this.rollGain.gain.setTargetAtTime(target, this.ctx.currentTime, 0.06);
    this.rollFilter.frequency.setTargetAtTime(300 + Math.min(1, speed / 13) * 800, this.ctx.currentTime, 0.1);
  }

  tone(freq, duration = 0.12, type = 'sine', gain = 0.12, slideTo = null, delay = 0) {
    if (!this.ctx || !this.enabled) return;
    const t0 = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(slideTo, t0 + duration);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    osc.connect(g).connect(this.master);
    osc.start(t0);
    osc.stop(t0 + duration + 0.02);
  }

  noise(duration = 0.3, gain = 0.12, type = 'highpass', freq = 700, delay = 0) {
    if (!this.ctx || !this.enabled) return;
    const t0 = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = freq;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    src.connect(filter).connect(g).connect(this.master);
    src.start(t0);
    src.stop(t0 + duration + 0.02);
  }

  click() { this.unlock(); this.tone(520, 0.055, 'triangle', 0.06, 380); }
  jump() { this.tone(260, 0.18, 'sine', 0.1, 520); this.noise(0.08, 0.03, 'highpass', 1800); }
  land(power = 1) { this.tone(110, 0.13, 'sine', 0.07 * power, 65); this.noise(0.08, 0.04 * power, 'lowpass', 500); }
  collide(power = 1) {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    if (now - this.lastCollide < 0.09) return;
    this.lastCollide = now;
    this.tone(150, 0.09, 'square', 0.025 * power, 80);
  }
  checkpoint() {
    [659, 880, 1174].forEach((f, i) => this.tone(f, 0.16, 'triangle', 0.09, null, i * 0.08));
  }
  boost() { this.tone(180, 0.3, 'sawtooth', 0.07, 900); this.noise(0.3, 0.06, 'bandpass', 900); }
  bounce() { this.tone(150, 0.42, 'sine', 0.14, 760); }
  countdown(n) { this.tone(n > 0 ? 440 : 880, 0.14, 'square', 0.07, n > 0 ? 420 : 900); }
  finish() {
    [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.5, 'triangle', 0.1, null, i * 0.1));
    [523, 784].forEach((f, i) => this.tone(f / 2, 0.65, 'sine', 0.05, null, i * 0.1));
    this.noise(0.5, 0.05, 'highpass', 1200);
  }
  fail() { this.tone(280, 0.35, 'sawtooth', 0.06, 90); }
  uiOpen() { this.tone(392, 0.08, 'triangle', 0.05, 523); }
  uiBack() { this.tone(523, 0.08, 'triangle', 0.05, 392); }
}

export const audio = new GameAudio();

