    };

    this.materials = new Map();
    this.geometries = new Map();
    this.lineMaterials = new Map();
    this.particleTexture = makeParticleTexture();
    this.cloudTexture = makeCloudTexture();

    this.setupScene();
    this.setupLights();
    this.setupSky();
    this.setupClouds();
    this.setupStars();
    this.setupFX();
