+    if (!el) continue;
+    el.classList.toggle('is-on', !!s[key]);
+    el.setAttribute('aria-pressed', String(!!s[key]));
+  }
+}
+
+function setSound(on, announce = false) {
+  store.setSetting('sound', !!on);
+  audio.setEnabled(!!on);
+  if (on) {
+    audio.unlock();
