+  }
+  syncSettingsUI();
+}
+
+function setGhost(on) {
+  store.setSetting('ghost', !!on);
+  game.ghostEnabled = !!on;
+  if (!on) game.ghostMesh.group.visible = false;
+  syncSettingsUI();
+  showToast(on ? 'Ghost replay on.' : 'Ghost replay off.');
+}
+
+async function enableTilt(on, silent = false) {
