394:   lineMat(color, opacity = 0.8) {
395:     const key = `${color}|${opacity}`;
396:     if (this.lineMaterials.has(key)) return this.lineMaterials.get(key);
397:     const mat = new THREE.LineBasicMaterial({ color, transparent: true, opacity, depthWrite: false });
398:     this.lineMaterials.set(key, mat);
