411:   cylGeo(rTop, rBottom, h, seg = 8) {
412:     const key = `cyl|${rTop}|${rBottom}|${h}|${seg}`;
413:     if (this.geometries.has(key)) return this.geometries.get(key);
414:     const geo = new THREE.CylinderGeometry(rTop, rBottom, h, seg);
415:     this.geometries.set(key, geo);
