430:     this.skyUniforms.sunColor.value.set(t.sun);
431:     this.scene.fog.color.set(t.fog);
432:     this.scene.fog.near = key === 'neon' ? 45 : 62;
433:     this.scene.fog.far = key === 'neon' ? 190 : 260;
434:     this.hemi.color.set(t.hemiSky);
435:     this.hemi.groundColor.set(t.hemiGround);
436:     this.hemi.intensity = key === 'neon' ? 0.62 : key === 'temple' ? 0.46 : 0.44;
437:     this.dir.color.set(t.light);
