804:   createRamp(p) {
805:     const t = this.theme;
806:     const topY = this.topOf(p);
807:     const angle = Math.atan2(STEP, CELL);
808:     const len = Math.sqrt(CELL * CELL + STEP * STEP);
809:     const thick = 0.38;
810:     const qYaw = new THREE.Quaternion().setFromAxisAngle(UP, yawFor(p.r));
811:     const qTilt = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(1, 0, 0), -angle);
812:     const quat = qYaw.clone().multiply(qTilt);
813:     const center = new THREE.Vector3(
814:       p.x * CELL,
815:       topY + STEP / 2 - (thick / 2) * Math.cos(angle),
816:       p.z * CELL,
817:     );
818:     const body = new THREE.Mesh(this.boxGeo(CELL * 0.94, thick, len, 0.08, 2), this.makeMat(t.bodySide, { roughness: 0.58 }));
819:     body.quaternion.copy(quat);
820:     body.position.copy(center);
821:     body.castShadow = true;
822:     body.receiveShadow = true;
823:     this.courseGroup.add(body);
824:     const normal = new THREE.Vector3(0, 1, 0).applyQuaternion(quat);
825:     const panel = new THREE.Mesh(this.boxGeo(CELL * 0.88, 0.07, len * 0.98, 0.05, 2), this.makeMat(t.top, { roughness: 0.62 }));
826:     panel.quaternion.copy(quat);
827:     panel.position.copy(center).addScaledVector(normal, thick / 2 - 0.02);
