423:   applyTheme(key) {
424:     const t = THEMES[key] || THEMES.sunrise;
425:     this.theme = t;
426:     this.themeKey = key;
427:     this.skyUniforms.top.value.set(t.skyTop);
428:     this.skyUniforms.mid.value.set(t.skyMid);
429:     this.skyUniforms.bottom.value.set(t.skyBottom);
430:     this.skyUniforms.sunColor.value.set(t.sun);
431:     this.scene.fog.color.set(t.fog);
432:     this.scene.fog.near = key === 'neon' ? 45 : 62;
433:     this.scene.fog.far = key === 'neon' ? 190 : 260;
434:     this.hemi.color.set(t.hemiSky);
435:     this.hemi.groundColor.set(t.hemiGround);
436:     this.hemi.intensity = key === 'neon' ? 0.62 : key === 'temple' ? 0.46 : 0.44;
437:     this.dir.color.set(t.light);
438:     this.dir.intensity = key === 'neon' ? 1.3 : 1.32;
439:     this.rim.color.set(t.accent);
440:     this.rim.intensity = key === 'neon' ? 0.8 : 0.32;
441:     for (const child of this.cloudGroup.children) child.material.color.set(t.cloud);
442:     this.starMat.opacity = key === 'neon' ? 0.9 : 0.12;
443:     this.renderer.toneMappingExposure = key === 'neon' ? 1.0 : 0.98;
444:   }
