750:   addEdgeOutlines(group, w, h, d, y, opacity = 0.45, color = null) {
751:     if (!this.unitEdges) {
752:       this.unitEdges = new THREE.EdgesGeometry(new THREE.BoxGeometry(1, 1, 1));
753:     }
754:     const lines = new THREE.LineSegments(this.unitEdges, this.lineMat(color || this.theme.accent, opacity));
755:     lines.scale.set(w, h, d);
756:     lines.position.y = y;
