760:   addSlab(x, z, topY, opts = {}) {
761:     const w = opts.w ?? CELL * 0.96;
762:     const d = opts.d ?? CELL * 0.96;
763:     const thick = opts.thick ?? 0.46;
764:     const rot = opts.rot || 0;
765:     const t = this.theme;
766:     const bodyMat = this.makeMat(opts.colorBody || t.body, { roughness: 0.55, metalness: 0.06 });
767:     const topMat = this.makeMat(opts.colorTop || t.top, { roughness: 0.66, metalness: 0.02 });
768:     const body = new THREE.Mesh(this.boxGeo(w, thick, d, 0.13, 2), bodyMat);
769:     body.position.set(x, topY - thick / 2, z);
770:     body.rotation.y = rot;
771:     body.castShadow = true;
772:     body.receiveShadow = true;
773:     this.courseGroup.add(body);
774: 
775:     const panel = new THREE.Mesh(this.boxGeo(w * 0.9, 0.09, d * 0.9, 0.06, 2), topMat);
776:     panel.position.set(x, topY - 0.045, z);
777:     panel.rotation.y = rot;
778:     panel.receiveShadow = true;
779:     this.courseGroup.add(panel);
780: 
781:     if (opts.outline !== false) {
782:       const group = new THREE.Group();
783:       group.position.set(x, 0, z);
784:       group.rotation.y = rot;
785:       this.courseGroup.add(group);
786:       this.addEdgeOutlines(group, w * 0.98, 0.13, d * 0.98, topY - 0.06, opts.outlineOpacity ?? 0.65, opts.outlineColor || null);
787:     }
788: 
789:     if (opts.collider !== false) {
790:       const quat = new THREE.Quaternion().setFromAxisAngle(UP, rot);
791:       const col = this.addColliderBox(
792:         new THREE.Vector3(x, topY - thick / 2, z),
793:         new THREE.Vector3(w / 2, thick / 2, d / 2),
794:         quat,
795:         opts.piece || null,
796:         opts.kind || 'platform',
797:       );
798:       col.topY = topY;
799:       return col;
800:     }
801:     return null;
