775: function openBuilder(map, opts = {}) {
776:   const draft = cloneMap(map);
777:   const editingId = opts.editingId || (draft.id && draft.id.startsWith('u-') ? draft.id : null);
778:   builderState = {
779:     map: draft,
780:     editingId,
781:     origin: opts.origin || 'maps',
782:     dirty: false,
783:   };
784:   currentRaceMap = null;
785:   currentRaceIsTest = false;
786:   testOrigin = false;
787:   game.enterBuilder(draft);
788:   showBuilderScreen();
789:   syncBuilderUI();
790:   audio.uiOpen();
791: }
