1068: async function enableTilt(on, silent = false) {
1069:   if (on) {
1070:     if (typeof DeviceOrientationEvent === 'undefined') {
1071:       if (!silent) showToast('This device has no tilt sensor — use the joystick.');
1072:       store.setSetting('tilt', false);
1073:       syncSettingsUI();
1074:       return;
1075:     }
1076:     if (typeof DeviceOrientationEvent.requestPermission === 'function') {
1077:       try {
1078:         const permission = await DeviceOrientationEvent.requestPermission();
1079:         if (permission !== 'granted') {
1080:           if (!silent) showToast('Motion access was denied — use the joystick.');
1081:           store.setSetting('tilt', false);
1082:           syncSettingsUI();
1083:           return;
1084:         }
1085:       } catch {
1086:         if (!silent) showToast('Motion access is unavailable here.');
1087:         store.setSetting('tilt', false);
1088:         syncSettingsUI();
1089:         return;
1090:       }
1091:     }
1092:     tiltBase = null;
1093:     tiltSeen = false;
1094:     window.addEventListener('deviceorientation', onDeviceOrientation);
1095:     game.input.tiltOn = true;
1096:     store.setSetting('tilt', true);
1097:     if (!silent) showToast('Tilt steering on — hold still to calibrate.');
1098:     setTimeout(() => {
1099:       if (!tiltSeen && game.input.tiltOn) {
1100:         showToast('No motion data yet — the joystick always works too.');
1101:       }
1102:     }, 2200);
1103:   } else {
1104:     window.removeEventListener('deviceorientation', onDeviceOrientation);
1105:     game.input.tiltOn = false;
1106:     game.input.tiltX = 0;
1107:     game.input.tiltY = 0;
1108:     tiltBase = null;
1109:     store.setSetting('tilt', false);
1110:     if (!silent) showToast('Tilt steering off.');
1111:   }
1112:   syncSettingsUI();
1113: }
1114: 
1115: function onDeviceOrientation(e) {
1116:   if (e.gamma == null && e.beta == null) return;
1117:   tiltSeen = true;
1118:   const gamma = e.gamma || 0;
1119:   const beta = e.beta || 0;
1120:   if (!tiltBase) tiltBase = { gamma, beta };
1121:   let dx = (gamma - tiltBase.gamma) / 21;
1122:   let dy = (beta - tiltBase.beta) / 21;
1123:   const angle = (screen.orientation && screen.orientation.angle) || 0;
1124:   let x = dx;
1125:   let y = -dy;
1126:   if (angle === 90) { x = -dy; y = -dx; }
1127:   else if (angle === 270 || angle === -90) { x = dy; y = dx; }
1128:   else if (Math.abs(angle) === 180) { x = -dx; y = dy; }
1129:   game.input.tiltX = clamp(x, -1, 1);
1130:   game.input.tiltY = clamp(y, -1, 1);
1131: }
