1285: function bindJoystick() {
1286:   const el = $('joystick');
1287:   const knob = $('joy-knob');
1288:   let center = { x: 0, y: 0 };
1289:   const setFrom = (clientX, clientY) => {
1290:     let dx = clientX - center.x;
1291:     let dy = clientY - center.y;
1292:     const dist = Math.hypot(dx, dy);
1293:     const max = 30;
1294:     if (dist > max) {
1295:       dx = (dx / dist) * max;
1296:       dy = (dy / dist) * max;
1297:     }
1298:     knob.style.transform = `translate(${dx}px, ${dy}px)`;
1299:     joystick.x = dx / max;
1300:     joystick.y = -dy / max;
1301:   };
1302:   el.addEventListener('pointerdown', (e) => {
1303:     if (game.mode !== 'race' || game.raceState === 'paused') return;
1304:     e.preventDefault();
1305:     e.stopPropagation();
1306:     audio.unlock();
1307:     const rect = el.getBoundingClientRect();
1308:     center = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
1309:     joystick.active = true;
1310:     joystick.id = e.pointerId;
1311:     try { el.setPointerCapture(e.pointerId); } catch { /* ignore */ }
1312:     setFrom(e.clientX, e.clientY);
1313:   });
1314:   el.addEventListener('pointermove', (e) => {
1315:     if (!joystick.active || joystick.id !== e.pointerId) return;
1316:     e.preventDefault();
1317:     setFrom(e.clientX, e.clientY);
1318:   });
1319:   const end = (e) => {
1320:     if (joystick.id !== e.pointerId) return;
1321:     resetJoystick();
1322:   };
1323:   el.addEventListener('pointerup', end);
1324:   el.addEventListener('pointercancel', end);
1325:   el.addEventListener('lostpointercapture', end);
1326: }
1327: 
1328: function bindCanvas() {
1329:   canvas.addEventListener('pointerdown', (e) => {
1330:     audio.unlock();
1331:     const hasScreens = !$('screen-pause').classList.contains('is-hidden')
1332:       || !$('screen-result').classList.contains('is-hidden')
1333:       || !$('modal-layer').classList.contains('is-hidden');
1334:     if (hasScreens) return;
1335:     activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
1336:     try { canvas.setPointerCapture(e.pointerId); } catch { /* ignore */ }
1337:     if (activePointers.size === 2) {
1338:       const pts = [...activePointers.values()];
1339:       pinchState = { dist: Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y) };
1340:       dragState = null;
1341:       return;
1342:     }
1343:     if (activePointers.size > 2) return;
1344:     dragState = {
1345:       id: e.pointerId,
1346:       lastX: e.clientX,
1347:       lastY: e.clientY,
1348:       moved: 0,
1349:       start: performance.now(),
1350:     };
1351:     if (game.mode === 'builder' && e.pointerType === 'mouse') {
1352:       game.updateBuilderHover(e.clientX, e.clientY);
1353:     }
1354:   });
1355: 
1356:   canvas.addEventListener('pointermove', (e) => {
1357:     if (activePointers.has(e.pointerId)) activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
1358:     if (activePointers.size >= 2 && pinchState) {
1359:       const pts = [...activePointers.values()];
1360:       if (pts.length >= 2) {
1361:         const dist = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y);
1362:         game.zoom((dist - pinchState.dist) * 0.9);
1363:         pinchState.dist = dist;
1364:       }
1365:       return;
1366:     }
1367:     if (dragState && dragState.id === e.pointerId) {
1368:       const dx = e.clientX - dragState.lastX;
1369:       const dy = e.clientY - dragState.lastY;
1370:       dragState.lastX = e.clientX;
1371:       dragState.lastY = e.clientY;
