215: export function decodeChallenge(code) {
216:   const text = String(code || '').trim();
217:   const body = text.startsWith('MR1.') ? text.slice(4) : text;
218:   if (!body || body.length > 200000) throw new Error('That code looks incomplete.');
219:   let payload;
220:   try {
221:     payload = JSON.parse(new TextDecoder().decode(b64ToBytes(body)));
222:   } catch {
223:     throw new Error('That challenge code is not valid.');
224:   }
225:   if (!payload || payload.v !== 1 || !Array.isArray(payload.pieces)) throw new Error('Unrecognized challenge code.');
226:   if (payload.pieces.length < 2 || payload.pieces.length > 1200) throw new Error('That course has an unusual size.');
227:   const pieces = [];
228:   for (const p of payload.pieces) {
229:     if (!p || !VALID.has(p.t)) continue;
230:     const x = Math.round(Number(p.x));
231:     const z = Math.round(Number(p.z));
232:     const l = Math.max(0, Math.min(5, Math.round(Number(p.l) || 0)));
233:     if (!Number.isFinite(x) || !Number.isFinite(z) || Math.abs(x) > 40 || Math.abs(z) > 40) continue;
234:     pieces.push({ t: p.t, x, z, l, r: Math.abs(Math.round(Number(p.r) || 0)) % 4 });
235:   }
236:   if (!pieces.some((p) => p.t === 'start') || !pieces.some((p) => p.t === 'finish')) {
237:     throw new Error('That course is missing a start or finish.');
238:   }
239:   return {
240:     id: `u-${Date.now().toString(36)}-${Math.floor(Math.random() * 999)}`,
241:     name: cleanName(payload.n || 'Shared Course', 34),
242:     author: cleanName(payload.a || 'Anon', 22),
243:     tagline: cleanName(payload.g || 'A shared marble course.', 80),
244:     theme: ['sunrise', 'neon', 'temple'].includes(payload.t) ? payload.t : 'sunrise',
245:     par: Math.max(8, Math.min(300, Number(payload.p) || 30)),
246:     difficulty: Math.max(1, Math.min(3, Number(payload.d) || 2)),
247:     pieces,
248:     creatorBest: Number.isFinite(payload.b) && payload.b > 2000 && payload.b < 3600000 ? Number(payload.b) : null,
249:     creatorName: cleanName(payload.a || 'Creator', 22),
250:     createdAt: Date.now(),
251:     shared: true,
252:   };
253: }
