function curveShape() {
  const center = -CELL / 2;
  const outer = CELL * 0.68;
  const inner = CELL * 0.22;
  const shape = new THREE.Shape();
  shape.absarc(center, center, outer, 0, Math.PI / 2, false);
  shape.lineTo(center, center + inner);
  shape.absarc(center, center, inner, Math.PI / 2, 0, true);
  shape.closePath();
  return shape;
}

