import { writeFile } from 'node:fs/promises';
const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
let targets;
for (let i = 0; i < 30; i++) {
  try { targets = await (await fetch('http://127.0.0.1:9222/json')).json(); if (targets.length) break; } catch {}
  await wait(300);
}
const target = targets?.find((item) => item.type === 'page');
if (!target) throw new Error('No Chrome page target');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, { once: true }); ws.addEventListener('error', reject, { once: true }); });
let nextId = 0;
const pending = new Map();
const exceptions = [];
ws.addEventListener('message', (event) => {
  const message = JSON.parse(event.data);
  if (message.method === 'Runtime.exceptionThrown') exceptions.push(message.params.exceptionDetails.text);
  if (message.id && pending.has(message.id)) {
    const { resolve, reject } = pending.get(message.id);
    pending.delete(message.id);
    if (message.error) reject(new Error(message.error.message)); else resolve(message.result);
  }
});
const send = (method, params = {}) => new Promise((resolve, reject) => {
  const id = ++nextId;
  pending.set(id, { resolve, reject });
  ws.send(JSON.stringify({ id, method, params }));
});
await send('Page.enable');
await send('Runtime.enable');
await wait(2500);
await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });
await wait(250);
const portrait = await send('Runtime.evaluate', { expression: `({w:innerWidth,h:innerHeight,docW:document.documentElement.scrollWidth,docH:document.documentElement.scrollHeight,bodyW:document.body.scrollWidth})`, returnByValue: true });
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 720, deviceScaleFactor: 1, mobile: false });
await wait(500);
const landscape = await send('Runtime.evaluate', { expression: `({title:document.title,w:innerWidth,h:innerHeight,docW:document.documentElement.scrollWidth,canvas:!!document.querySelector('canvas'),text:document.body.innerText.slice(0,240)})`, returnByValue: true });
const image = await send('Page.captureScreenshot', { format: 'jpeg', quality: 85, fromSurface: true, captureBeyondViewport: false });
await writeFile('/tmp/opencode/marble-landscape-latest.jpg', Buffer.from(image.data, 'base64'));
console.log(JSON.stringify({portrait: portrait.result.value, landscape: landscape.result.value, exceptions, screenshot: '/tmp/opencode/marble-landscape-latest.jpg'}, null, 2));
ws.close();
