272: export function courseBounds(pieces) {
273:   let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity, minL = 0, maxL = 0;
274:   for (const p of pieces) {
275:     minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
276:     minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
277:     minL = Math.min(minL, p.l); maxL = Math.max(maxL, p.l);
278:   }
279:   if (!pieces.length) return { minX: -2, maxX: 2, minZ: -2, maxZ: 2, minL: 0, maxL: 0 };
280:   return { minX, maxX, minZ, maxZ, minL, maxL };
281: }
