    meta.appendChild(warn);
  }
  meta.append(document.createTextNode(`${map.pieces.length} pieces · ${checkpoints} checkpoint${checkpoints === 1 ? '' : 's'} · PAR ≈ ${formatTime(estimatedPar(map.pieces) * 1000, false)}`));
