const offsets = [[1,0,'+x'],[0,1,'+z'],[-1,0,'-x'],[0,-1,'-z']];
const ports = [['+x','+z'],['+x','-z'],['-x','-z'],['-x','+z']];
for (const map of BUILTIN_MAPS) {
  for (const curve of map.pieces.filter((p) => p.t === 'curve')) {
    const adjacent = offsets.filter(([dx,dz]) => map.pieces.some((p) => p.x === curve.x+dx && p.z === curve.z+dz && p.l === curve.l)).map(([, , d]) => d);
    const expected = ports[curve.r % 4];
    const missingPorts = expected.filter((port) => !adjacent.includes(port));
    if (missingPorts.length) throw new Error(`${map.id} curve ${curve.x},${curve.z} r${curve.r}: expected ${expected}, found ${adjacent}`);
    console.log(`${map.id}: curve (${curve.x},${curve.z}) r${curve.r} connects ${expected.join(' + ')}`);
  }
}
for (const angle of [0, Math.PI/4, Math.PI/2]) {
  const tangent = [Math.sin(angle), -Math.cos(angle)];
  const yaw = Math.PI-angle;
  const colliderAxis = [Math.sin(yaw), Math.cos(yaw)];
  const dot = tangent[0]*colliderAxis[0] + tangent[1]*colliderAxis[1];
  if (Math.abs(Math.abs(dot)-1) > 1e-9) throw new Error(`collider tangent mismatch at ${angle}: ${dot}`);
}
console.log('Curve collider tangent verified at both endpoints and midpoint.');
